import math
import re
import unittest
import xml.etree.ElementTree as ET
from pathlib import Path

SVG = "http://www.w3.org/2000/svg"
TARGET = Path(__file__).resolve().parent / "pelican.svg"
REQUIRED_IDS = {"beach", "sea", "sand", "bicycle", "wheel-rear", "wheel-front",
                "frame", "pelican", "bill", "pouch", "eye"}


def tag(el):
    return el.tag.split("}")[-1]


def num(value, default=None):
    try:
        return float(str(value).strip())
    except (TypeError, ValueError):
        return default


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        cls.root = ET.fromstring(cls.raw)
        cls.byid = {}
        for el in cls.root.iter():
            ident = el.get("id")
            if ident:
                cls.byid.setdefault(ident, el)

    def circles_in(self, ident):
        node = self.byid.get(ident)
        self.assertIsNotNone(node, "missing id=%s" % ident)
        found = [el for el in node.iter() if tag(el) == "circle"]
        if tag(node) == "circle":
            found.append(node)
        self.assertTrue(found, "no <circle> inside id=%s" % ident)
        return found

    def wheel(self, ident):
        """The wheel is the largest circle in the group: rim, not hub or spoke dot."""
        best = max(self.circles_in(ident), key=lambda c: num(c.get("r"), 0) or 0)
        r = num(best.get("r"))
        cx, cy = num(best.get("cx")), num(best.get("cy"))
        for value, name in ((r, "r"), (cx, "cx"), (cy, "cy")):
            self.assertIsNotNone(value, "wheel %s has no numeric %s" % (ident, name))
        return cx, cy, r

    # --- structure -----------------------------------------------------
    def test_root_is_svg_with_viewbox(self):
        self.assertEqual(tag(self.root), "svg")
        box = (self.root.get("viewBox") or "").replace(",", " ").split()
        self.assertEqual(len(box), 4, "viewBox must have 4 numbers, got %r" % box)
        w, h = num(box[2]), num(box[3])
        self.assertTrue(w and w >= 100, "viewBox width too small: %r" % w)
        self.assertTrue(h and h >= 100, "viewBox height too small: %r" % h)

    def test_required_ids_present(self):
        missing = sorted(REQUIRED_IDS - set(self.byid))
        self.assertEqual(missing, [], "missing required ids: %s" % missing)

    # --- self-contained -------------------------------------------------
    def test_no_external_references(self):
        for el in self.root.iter():
            for key, value in el.attrib.items():
                if key.split("}")[-1] in ("href", "src") and re.match(r"\s*(https?:)?//", value or ""):
                    self.fail("external reference in %s: %s" % (tag(el), value))
        self.assertNotIn("@import", self.raw)
        self.assertFalse(re.search(r"url\(\s*['\"]?(https?:)?//", self.raw),
                         "external url() reference")

    def test_no_script_or_raster(self):
        kinds = {tag(el) for el in self.root.iter()}
        self.assertNotIn("script", kinds, "SVG must not contain <script>")
        self.assertNotIn("image", kinds, "SVG must be vector only, no <image>")
        self.assertNotIn("foreignObject", kinds)

    # --- geometry, measured not asserted in prose -----------------------
    def test_two_wheels_same_size(self):
        _, _, r1 = self.wheel("wheel-rear")
        _, _, r2 = self.wheel("wheel-front")
        self.assertAlmostEqual(r1, r2, delta=max(1.0, 0.02 * max(r1, r2)),
                               msg="wheels differ in radius: %s vs %s" % (r1, r2))

    def test_wheels_sit_on_one_axle_line(self):
        _, cy1, r = self.wheel("wheel-rear")
        _, cy2, _ = self.wheel("wheel-front")
        self.assertLessEqual(abs(cy1 - cy2), 0.05 * r,
                             "wheel centres not level: cy %s vs %s" % (cy1, cy2))

    def test_wheels_do_not_overlap(self):
        cx1, _, r1 = self.wheel("wheel-rear")
        cx2, _, r2 = self.wheel("wheel-front")
        gap = abs(cx2 - cx1)
        self.assertGreaterEqual(gap, r1 + r2,
                                "wheels overlap: centres %s apart, radii %s and %s"
                                % (gap, r1, r2))

    def test_wheelbase_is_plausible(self):
        cx1, _, r = self.wheel("wheel-rear")
        cx2, _, _ = self.wheel("wheel-front")
        ratio = abs(cx2 - cx1) / r
        self.assertTrue(2.0 <= ratio <= 6.0,
                        "wheelbase/radius = %.2f, outside a bicycle's 2.0-6.0" % ratio)

    def test_pelican_rides_above_the_wheels(self):
        _, cy, r = self.wheel("wheel-rear")
        eye = self.byid["eye"]
        eye_y = num(eye.get("cy"))
        if eye_y is None:
            eye_y = num(eye.get("y"))
        self.assertIsNotNone(eye_y, "eye needs a numeric cy or y")
        self.assertLess(eye_y, cy - r,
                        "pelican's eye at y=%s is not above the wheel top y=%s"
                        % (eye_y, cy - r))

    def test_bill_and_pouch_are_distinct_elements(self):
        self.assertIsNot(self.byid["bill"], self.byid["pouch"],
                         "bill and pouch must be separate elements")

    def test_beach_layers_ordered_sea_above_sand(self):
        """On a beach seen from the side, the sea sits higher than the sand."""
        def top(ident):
            el = self.byid[ident]
            candidates = [num(n.get("y")) for n in el.iter() if n.get("y") is not None]
            if el.get("y") is not None:
                candidates.append(num(el.get("y")))
            candidates = [c for c in candidates if c is not None]
            return min(candidates) if candidates else None
        sea_y, sand_y = top("sea"), top("sand")
        if sea_y is None or sand_y is None:
            self.skipTest("sea/sand not expressed with y attributes")
        self.assertLess(sea_y, sand_y,
                        "sea (y=%s) must be above sand (y=%s)" % (sea_y, sand_y))


if __name__ == "__main__":
    unittest.main()
